{"path":"README.md","content":"HVAC Premium Website Template

Overview
- Niche: HVAC
- Slug: hvac-premium-2026-02-15T13-05-21-802Z
- Fully static, responsive, accessible, SEO-ready.
- Works 100% offline. No external assets or CDNs.

Structure
- index.html — Home
- services.html — All services overview
- pricing.html — Packages and transparent pricing
- financing.html — Financing options and calculator
- about.html — Company story, team, certifications
- reviews.html — Testimonials and ratings
- book.html — Booking form and live estimate
- contact.html — Contact form and details
- assets/css/styles.css — Stylesheet (system font stack only)
- assets/js/main.js — Interactivity (nav, forms, calculators)
- assets/img/avatar-01.svg — Team/review avatar graphic
- assets/img/hero-abstract.svg — Hero background art
- template.json — Template metadata
- fields.json — Dynamic field definitions

Dynamic Placeholders
Replace these tokens across files with your business data:
- {{BUSINESS_NAME}}
- {{TAGLINE}}
- {{PHONE}}
- {{EMAIL}}
- {{ADDRESS}}
- {{CITY}}
- {{STATE}}
- {{ZIP}}
- {{HOURS}}
- {{PRIMARY_CTA_URL}}
- {{PRIMARY_CTA_LABEL}}

Getting Started
1) Open the files in a code editor.
2) Search-and-replace the placeholders above.
3) Keep assets directory structure intact.
4) Open index.html in a browser to preview locally.

Accessibility & SEO
- Semantic HTML, skip link, focus styles, sufficient color contrast.
- Meta, OpenGraph, and JSON-LD LocalBusiness schema on every page.

Customization Tips
- Colors: Edit CSS variables in :root within assets/css/styles.css.
- Buttons/components: Reuse .btn, .card, .grid utilities.
- Calculator defaults: Adjust in assets/js/main.js (financing + booking).

Notes
- Do not add external fonts or libraries to preserve offline capability.
- hero-abstract.svg is used as a decorative background; ensure alt="" where appropriate.

License
- Provided as-is. You may modify and use in client projects.
"}
{"path":"assets/css/styles.css","content":"/* HVAC Premium Template Styles */
:root{
  --brand-600:#1f6feb;
  --brand-700:#1556c0;
  --brand-500:#3b82f6;
  --accent-500:#f59e0b;
  --accent-600:#d97706;
  --ink-900:#0b1220;
  --ink-800:#141c2e;
  --ink-700:#233049;
  --ink-600:#3b4860;
  --ink-500:#5b6780;
  --muted-400:#97a0b3;
  --muted-300:#c7cdda;
  --muted-200:#e3e7ef;
  --muted-100:#f4f6fb;
  --success-500:#16a34a;
  --danger-500:#ef4444;
  --shadow-rgb:17, 24, 39;
  --radius-2:10px;
  --radius-3:16px;
  --radius-pill:999px;
  --container:1200px;
  --pad:clamp(16px,2vw,28px);
  --pad-lg:clamp(28px,4vw,56px);
  --elev-1:0 4px 16px rgba(var(--shadow-rgb),.08);
  --elev-2:0 10px 30px rgba(var(--shadow-rgb),.12);
  --ring:0 0 0 3px rgba(31,111,235,.25);
}
*{box-sizing:border-box}
html{scroll-behavior:smooth}
body{
  margin:0; color:var(--ink-800); background:#fff;
  font:16px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Helvetica Neue",Arial,"Noto Sans","Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol","Noto Color Emoji",sans-serif;
}
img,svg{max-width:100%; height:auto}
.container{max-width:var(--container); margin-inline:auto; padding-inline:var(--pad)}
.section{padding: clamp(48px,7vw,96px) 0}
.grid{display:grid; gap:clamp(16px,2.5vw,28px)}
.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}
.grid-4{grid-template-columns:repeat(4,minmax(0,1fr))}
@media (max-width: 900px){.grid-2,.grid-3,.grid-4{grid-template-columns:1fr}}

h1,h2,h3{color:var(--ink-900); line-height:1.15; margin:0 0 .5em}
h1{font-size:clamp(32px,4.5vw,52px); letter-spacing:-.015em}
h2{font-size:clamp(24px,3vw,36px)}
h3{font-size:clamp(20px,2.4vw,26px)}
p{margin:0 0 1em; color:var(--ink-700)}
.lead{font-size:clamp(18px,2vw,20px); color:var(--ink-700)}
.small{font-size:14px; color:var(--ink-600)}
.muted{color:var(--muted-400)}
.center{text-align:center}
.right{text-align:right}

.btn{display:inline-flex; align-items:center; justify-content:center; gap:.5rem; padding:.85rem 1.25rem; border-radius:var(--radius-pill); text-decoration:none; font-weight:600; transition:.2s ease; border:1px solid transparent}
.btn:focus-visible{outline:none; box-shadow:var(--ring)}
.btn-primary{background:linear-gradient(180deg,var(--brand-500),var(--brand-700)); color:#fff}
.btn-primary:hover{filter:brightness(1.05); transform:translateY(-1px)}
.btn-secondary{background:#fff; color:var(--ink-900); border-color:var(--muted-200)}
.btn-secondary:hover{background:var(--muted-100)}
.btn-ghost{background:transparent; color:var(--brand-700)}
.badge{display:inline-block; padding:.35rem .6rem; border-radius:8px; background:var(--muted-100); color:var(--ink-700); font-weight:600; font-size:.85rem}

.header{position:sticky; top:0; z-index:50; background:#fff; box-shadow:0 1px 0 var(--muted-200)}
.topbar{display:flex; align-items:center; justify-content:space-between; gap:12px; padding:.4rem var(--pad); background:var(--muted-100); color:var(--ink-700); font-size:.9rem}
.topbar a{color:inherit; text-decoration:none}
.nav{display:flex; align-items:center; justify-content:space-between; gap:16px; padding:.6rem var(--pad)}
.logo{display:flex; align-items:center; gap:.6rem; text-decoration:none}
.logo-mark{width:38px; height:38px; border-radius:10px; background:linear-gradient(135deg,var(--brand-700),var(--brand-500)); display:grid; place-items:center; color:#fff; box-shadow:var(--elev-1)}
.logo-title{font-weight:800; color:var(--ink-900)}
.menu{display:flex; gap:6px; align-items:center}
.menu a{padding:.6rem .8rem; border-radius:8px; color:var(--ink-800); text-decoration:none; font-weight:600}
.menu a:hover{background:var(--muted-100)}
.menu a[aria-current="page"]{background:var(--ink-900); color:#fff}
.menu-actions{display:flex; gap:8px; align-items:center}

.nav-toggle{display:none; background:#fff; border:1px solid var(--muted-200); padding:.6rem .7rem; border-radius:10px}
.nav-toggle:focus-visible{box-shadow:var(--ring)}
@media (max-width: 980px){
  .menu{position:fixed; inset:64px 0 auto 0; background:#fff; box-shadow:0 12px 30px rgba(var(--shadow-rgb),.15); border-top:1px solid var(--muted-200); padding:12px; display:none; flex-direction:column}
  .menu.open{display:flex}
  .menu-actions{display:none}
  .nav-toggle{display:inline-flex}
}

.hero{position:relative; overflow:hidden; background:linear-gradient(0deg,#fff,rgba(244,246,251,.6)), url('../img/hero-abstract.svg') center/cover no-repeat}
.hero .container{display:grid; grid-template-columns: 1.05fr .95fr; gap:clamp(20px,4vw,40px); align-items:center}
.hero-visual{display:grid; place-items:center}
.hero-card{background:#fff; border:1px solid var(--muted-200); border-radius:var(--radius-3); padding:clamp(16px,2.2vw,22px); box-shadow:var(--elev-1)}
.hero-card h3{margin-bottom:.35rem}
.hero-checks{display:grid; gap:8px; margin-top:10px}
.hero-checks li{display:flex; align-items:center; gap:10px}
.hero-actions{display:flex; gap:10px; align-items:center; flex-wrap:wrap; margin-top:clamp(16px,2vw,22px)}

.card{background:#fff; border:1px solid var(--muted-200); border-radius:var(--radius-3); padding:clamp(16px,2.2vw,22px); box-shadow:var(--elev-1)}
.card:hover{transform:translateY(-2px); box-shadow:var(--elev-2)}
.card h3{margin-bottom:.25rem}
.icon{width:22px; height:22px; color:var(--brand-700)}
.icon-xl{width:48px; height:48px}

.process{counter-reset: step}
.process .step{position:relative; padding-left:56px}
.process .step:before{counter-increment:step; content: counter(step); position:absolute; left:0; top:0; width:40px; height:40px; border-radius:12px; background:linear-gradient(135deg,var(--brand-500),var(--brand-700)); color:#fff; display:grid; place-items:center; font-weight:800; box-shadow:var(--elev-1)}

.testimonial{display:grid; gap:12px}
.stars{display:inline-flex; gap:2px; color:#f6c21b}
.quote{font-size:1.05rem}
.review-meta{display:flex; align-items:center; gap:10px}
.avatar{width:44px; height:44px; border-radius:50%; border:1px solid var(--muted-200); background:#fff}

.pricing{display:grid; gap:18px}
.plan{border-radius:16px; border:1px solid var(--muted-200); background:#fff; padding:clamp(18px,2.4vw,28px); box-shadow:var(--elev-1); display:grid; gap:14px}
.plan.featured{border-color:var(--brand-600); box-shadow:0 10px 30px rgba(31,111,235,.12)}
.price{font-size:clamp(28px,3.2vw,38px); font-weight:800; color:var(--ink-900)}
.included{display:grid; gap:8px; margin-top:8px}
.included li{display:flex; gap:10px; align-items:flex-start}

form{display:grid; gap:12px}
.form-grid{display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:12px}
@media (max-width: 720px){.form-grid{grid-template-columns:1fr}}
.field label{display:block; font-weight:700; font-size:.95rem; margin-bottom:6px}
.input,.select,.textarea{width:100%; border:1px solid var(--muted-300); background:#fff; border-radius:10px; padding:.8rem .9rem; font-size:1rem}
.input:focus,.select:focus,.textarea:focus{outline:none; box-shadow:var(--ring); border-color:var(--brand-600)}
.help{font-size:.85rem; color:var(--muted-400)}
.notice{padding:.8rem 1rem; background:var(--muted-100); border:1px solid var(--muted-200); border-radius:12px}
.error{color:var(--danger-500)}
.success{color:var(--success-500)}

.faq details{border:1px solid var(--muted-200); border-radius:12px; padding:10px 14px; background:#fff}
.faq summary{cursor:pointer; font-weight:700}
.faq details[open]{box-shadow:var(--elev-1)}

.footer{background:linear-gradient(0deg,var(--muted-100),#fff); border-top:1px solid var(--muted-200)}
.footer .cols{display:grid; grid-template-columns:2fr 1fr 1fr; gap:24px}
@media (max-width: 900px){.footer .cols{grid-template-columns:1fr}}
.footer a{color:var(--ink-800); text-decoration:none}
.footer a:hover{text-decoration:underline}
.subfooter{display:flex; justify-content:space-between; align-items:center; gap:12px; padding:.9rem 0; border-top:1px solid var(--muted-200); font-size:.9rem}

.cta-banner{border-radius:20px; padding:clamp(18px,3vw,28px); background:linear-gradient(135deg,var(--brand-500),var(--brand-700)); color:#fff; display:grid; gap:10px; align-items:center}
.cta-banner .actions{display:flex; gap:10px; flex-wrap:wrap}

.skip-link{position:absolute; left:-999px; top:auto; width:1px; height:1px; overflow:hidden}
.skip-link:focus{position:fixed; left:10px; top:10px; width:auto; height:auto; background:#fff; border:2px solid var(--brand-600); padding:.5rem .75rem; z-index:9999}

.table{width:100%; border-collapse:collapse; overflow:hidden; border-radius:12px; border:1px solid var(--muted-200)}
.table th,.table td{padding:12px 14px; border-top:1px solid var(--muted-200); text-align:left}
.table thead th{background:var(--muted-100); border-top:none}

.kpi{display:grid; grid-auto-flow:column; gap:14px; align-items:center}
.kpi strong{font-size:clamp(22px,3vw,28px)}

hr{border:0; border-top:1px solid var(--muted-200); margin:24px 0}

/* Utilities */
.mt-0{margin-top:0}
.mt-1{margin-top:8px}
.mt-2{margin-top:16px}
.mt-3{margin-top:24px}
.mt-4{margin-top:32px}
.mb-0{margin-bottom:0}
.mb-1{margin-bottom:8px}
.mb-2{margin-bottom:16px}
.mb-3{margin-bottom:24px}
.mb-4{margin-bottom:32px}

/* Print tweaks */
@media print{
  .header,.cta-banner,.nav-toggle{display:none!important}
  a[href]:after{content:" (" attr(href) ")"}
}
"}
{"path":"assets/js/main.js","content":"/* HVAC Premium Template JS */
(function(){
  const $ = (sel, ctx=document) => ctx.querySelector(sel);
  const $$ = (sel, ctx=document) => Array.from(ctx.querySelectorAll(sel));

  document.addEventListener('DOMContentLoaded', () => {
    // Mobile nav toggle
    const toggle = $('#menuToggle');
    const menu = $('#siteMenu');
    if(toggle && menu){
      toggle.addEventListener('click', () => {
        const isOpen = menu.classList.toggle('open');
        toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      });
    }

    // Current year in footer
    const y = $('#year');
    if(y){ y.textContent = new Date().getFullYear(); }

    // Simple form validation helper
    $$('.js-validate').forEach(form => {
      form.addEventListener('submit', (e) => {
        if(!form.checkValidity()){
          e.preventDefault();
          form.querySelectorAll(':invalid')[0]?.focus();
        }
      });
    });

    // Booking estimator
    initBookingEstimator();

    // Financing calculator
    initFinanceCalc();
  });

  function money(n){
    try { return new Intl.NumberFormat(undefined,{style:'currency',currency:'USD'}).format(n); }
    catch(e){ return `$${n.toFixed(2)}`; }
  }

  function initBookingEstimator(){
    const scope = $('#bookingEstimator');
    if(!scope) return;
    const service = $('#svc');
    const priority = $('#priority');
    const extras = $$('#extras input[type=checkbox]', scope);
    const outTotal = $('#estTotal');
    const outMonthly = $('#estMonthly');

    const baseMap = {
      inspect: 89,
      tuneup: 159,
      repair: 289,
      install: 4890
    };

    const multipliers = { standard:1, urgent:1.35 };

    function compute(){
      const svc = service?.value || 'inspect';
      const pri = priority?.value || 'standard';
      let total = baseMap[svc] || 0;
      extras.forEach(x => { if(x.checked){ total += Number(x.dataset.price||0); }});
      total *= multipliers[pri] || 1;
      if(outTotal) outTotal.textContent = money(total);
      // default financing calc 7.99% APR 36 months
      const apr = 0.0799, months = 36;
      const r = apr/12; // monthly rate
      const m = (total>0 && r>0) ? (total * r) / (1 - Math.pow(1+r, -months)) : (total/months);
      if(outMonthly) outMonthly.textContent = money(isFinite(m)? m : 0);
    }

    [service, priority, ...extras].forEach(el => el && el.addEventListener('change', compute));
    compute();
  }

  function initFinanceCalc(){
    const scope = $('#financeCalc');
    if(!scope) return;
    const amount = $('#finAmount');
    const apr = $('#finAPR');
    const months = $('#finMonths');
    const out = $('#finResult');

    function calc(){
      const P = Number(amount?.value||0);
      const R = Number(apr?.value||0)/100/12;
      const N = Math.max(1, Number(months?.value||0));
      let pay = 0;
      if(R>0){ pay = (P * R) / (1 - Math.pow(1+R, -N)); }
      else { pay = P / N; }
      if(out){ out.textContent = isFinite(pay) ? money(pay) : '$0.00'; }
    }

    [amount, apr, months].forEach(el => el && el.addEventListener('input', calc));
    calc();
  }
})();
"}
