{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>{{BUSINESS_NAME}} | {{TAGLINE}}</title>
  <meta name="description" content="{{BUSINESS_NAME}} provides trusted HVAC installation, repair, and maintenance in {{CITY}}, {{STATE}}. Fast response, transparent pricing, and comfort engineered for every season.">
  <link rel="canonical" href="/">
  <meta property="og:title" content="{{BUSINESS_NAME}} — {{TAGLINE}}">
  <meta property="og:description" content="Trusted HVAC installation, repair, and maintenance in {{CITY}}, {{STATE}}. Call {{PHONE}}.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta property="og:image:alt" content="Comfort-first HVAC service">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="preload" as="image" href="assets/img/hero-abstract.svg">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">
  {
    "@context":"https://schema.org",
    "@type":"HVACBusiness",
    "name":"{{BUSINESS_NAME}}",
    "image":["assets/img/hero-abstract.svg","assets/img/avatar-01.svg"],
    "telephone":"{{PHONE}}",
    "email":"{{EMAIL}}",
    "address":{
      "@type":"PostalAddress",
      "streetAddress":"{{ADDRESS}}",
      "addressLocality":"{{CITY}}",
      "addressRegion":"{{STATE}}",
      "postalCode":"{{ZIP}}",
      "addressCountry":"US"
    },
    "openingHours":"{{HOURS}}",
    "areaServed":"{{CITY}}, {{STATE}}",
    "url":"/"
  }
  </script>
</head>
<body>
  <a href="#main" class="skip-link">Skip to content</a>
  <header class="header" role="banner">
    <div class="topbar">
      <div>
        <a href="tel:{{PHONE}}" aria-label="Call us at {{PHONE}}">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M6.62 10.79a15.91 15.91 0 006.59 6.59l2.2-2.2a1 1 0 011.02-.24c1.12.37 2.33.57 3.57.57a1 1 0 011 1V21a1 1 0 01-1 1C10.4 22 2 13.6 2 3a1 1 0 011-1h3.5a1 1 0 011 1c0 1.24.2 2.45.57 3.57a1 1 0 01-.24 1.02l-2.2 2.2z"/></svg>
          <strong>{{PHONE}}</strong>
        </a>
        <span class="muted"> • </span>
        <a href="mailto:{{EMAIL}}" aria-label="Email us at {{EMAIL}}">
          <svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M20 4H4a2 2 0 00-2 2v12a2 2 0 002 2h16a2 2 0 002-2V6a2 2 0 00-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z"/></svg>
          {{EMAIL}}
        </a>
      </div>
      <div class="small">Open today: {{HOURS}}</div>
    </div>
    <nav class="nav" aria-label="Primary">
      <a class="logo" href="/">
        <span class="logo-mark" aria-hidden="true">
