{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Book Service | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Book HVAC service with {{BUSINESS_NAME}} in minutes. Choose service type, date, and priority. Instant estimate and optional financing.">
  <link rel="canonical" href="/book.html">
  <meta property="og:title" content="Book HVAC Service — {{BUSINESS_NAME}}">
  <meta property="og:description" content="Schedule your service online. Transparent pricing and 24/7 emergency options.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/book.html">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta property="og:image:alt" content="Online booking">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">
  {
    "@context":"https://schema.org",
    "@type":"ScheduleAction",
    "agent":{"@type":"Organization","name":"{{BUSINESS_NAME}}"},
    "location":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"{{ADDRESS}}","addressLocality":"{{CITY}}","addressRegion":"{{STATE}}","postalCode":"{{ZIP}}"}},
    "target":"/book.html"
  }
  </script>
</head>
<body>
  <a href="#main" class="skip-link">Skip to content</a>
  <header class="header" role="banner">
    <div class="topbar"><div><a href="tel:{{PHONE}}"><strong>{{PHONE}}</strong></a> <span class="muted">•</span> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div><div class="small">Open today: {{HOURS}}</div></div>
    <nav class="nav" aria-label="Primary">
      <a class="logo" href="/"><span class="logo-mark" aria-hidden="true"></span><span class="logo-title">{{BUSINESS_NAME}}</span></a>
      <button id="menuToggle" class="nav-toggle" aria-expanded="false" aria-controls="siteMenu" aria-label="Toggle menu"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M3 6h18v2H3zm0 5h18v2H3zm0 5h18v2H3z"/></svg></button>
      <div class="menu" id="siteMenu">
        <a href="/services.html">Services</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/financing.html">Financing</a>
        <a href="/about.html">About</a>
        <a href="/reviews.html">Reviews</a>
        <a href="/book.html" aria-current="page" class="badge">Book</a>
        <a href="/contact.html">Contact</a>
      </div>
      <div class="menu-actions">
        <a class="btn btn-secondary" href="tel:{{PHONE}}">Call {{PHONE}}</a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </nav>
  </header>

  <main id="main">
    <section class="section hero" aria-label="Booking hero">
      <div class="container">
        <div>
          <span class="badge">Book in minutes</span>
          <h1>Schedule your service</h1>
          <p class="lead">Pick a time that works for you. We’ll confirm and keep you updated every step of the way.</p>
        </div>
        <div aria-hidden="true" class="hero-visual"><img src="assets/img/hero-abstract.svg" alt="" style="border-radius:16px; border:1px solid var(--muted-200)"></div>
      </div>
    </section>

    <section class="section">
      <div class="container grid grid-2">
        <form class="card js-validate" method="post" action="#" novalidate aria-describedby="bookHelp">
          <h2 class="mt-0">Your details</h2>
          <div class="form-grid">
            <div class="field"><label for="name">Full name</label><input class="input" id="name" name="name" required autocomplete="name"></div>
            <div class="field"><label for="phone">Phone</label><input class="input" id="phone" name="phone" type="tel" required autocomplete="tel"></div>
            <div class="field"><label for="email">Email</label><input class="input" id="email" name="email" type="email" required autocomplete="email"></div>
            <div class="field"><label for="addr">Service address</label><input class="input" id="addr" name="addr" required autocomplete="street-address"></div>
            <div class="field"><label for="city">City</label><input class="input" id="city" name="city" required value="{{CITY}}"></div>
            <div class="field"><label for="zip">ZIP</label><input class="input" id="zip" name="zip" required value="{{ZIP}}"></div>
          </div>
          <p id="bookHelp" class="help">We respect your privacy. We’ll never share your information.</p>
          <hr>
          <h2>Service details</h2>
          <div id="bookingEstimator">
            <div class="form-grid">
              <div class="field"><label for="svc">Service</label>
                <select class="select" id="svc" name="service" required>
                  <option value="inspect">Service call — diagnostic</option>
                  <option value="tuneup">Precision tune‑up</option>
                  <option value="repair">Repair — quote after diagnostic</option>
                  <option value="install">Install/replace system</option>
                </select>
              </div>
              <div class="field"><label for="priority">Priority</label>
                <select class="select" id="priority" name="priority" required>
                  <option value="standard">Standard</option>
                  <option value="urgent">Urgent (24/7)</option>
                </select>
              </div>
              <div class="field"><label for="date">Preferred date</label><input class="input" id="date" type="date" name="date" required></div>
              <div class="field"><label for="time">Preferred time</label><input class="input" id="time" type="time" name="time" required></div>
            </div>
            <fieldset id="extras" class="mt-2" aria-describedby="xhelp">
              <legend class="small"><strong>Add‑ons</strong></legend>
              <label class="small"><input type="checkbox" data-price="39"> High‑MERV filter</label>
              <label class="small"><input type="checkbox" data-price="79"> Condenser rinse</label>
              <label class="small"><input type="checkbox" data-price="149"> Air quality test</label>
              <p id="xhelp" class="help">Optional items that can enhance performance and air quality.</p>
            </fieldset>
            <div class="notice mt-2">
              <div class="grid grid-2">
                <div>
                  <div class="small muted">Estimated total</div>
                  <div id="estTotal" class="price" aria-live="polite">$0.00</div>
                </div>
                <div>
                  <div class="small muted">As low as</div>
                  <div id="estMonthly" class="price" aria-live="polite">$0.00</div>
                  <div class="small muted">per month with financing</div>
                </div>
              </div>
            </div>
          </div>
          <hr>
          <button class="btn btn-primary" type="submit">Confirm request</button>
          <p class="small muted mt-1">We’ll confirm by phone at {{PHONE}} or email {{EMAIL}}.</p>
        </form>

        <aside class="card" aria-label="Booking sidebar">
          <h2 class="mt-0">What to expect</h2>
          <ul class="included" role="list">
            <li><svg class="icon" viewBox="0 0 24 24"><path fill="currentColor" d="M9 16.2L5.5 12.7l-1.4 1.4L9 19l11.3-11.3-1.4-1.4z"/></svg> Reminder before arrival</li>
            <li><svg class="icon" viewBox="0 0 24 24"><path fill="currentColor" d="M9 16.2L5.5 12.7l-1.4 1.4L9 19l11.3-11.3-1.4-1.4z"/></svg> Shoe covers & clean work area</li>
            <li><svg class="icon" viewBox="0 0 24 24"><path fill="currentColor" d="M9 16.2L5.5 12.7l-1.4 1.4L9 19l11.3-11.3-1.4-1.4z"/></svg> Transparent quote before work</li>
          </ul>
          <hr>
          <h3>Need urgent help?</h3>
          <p class="small">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> for 24/7 emergency service.</p>
          <div class="mt-1"><a class="btn btn-secondary" href="/pricing.html">See pricing</a></div>
        </aside>
      </div>
    </section>
  </main>

  <footer class="footer" role="contentinfo">
    <div class="container section">
      <div class="cols">
        <div><a class="logo" href="/"><span class="logo-mark" aria-hidden="true"></span><span class="logo-title">{{BUSINESS_NAME}}</span></a><p class="mt-2">{{TAGLINE}}</p></div>
        <div><h3>Contact</h3><p class="small"><strong>Phone:</strong> <a href="tel:{{PHONE}}">{{PHONE}}</a></p><p class="small"><strong>Email:</strong> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p><p class="small"><strong>Hours:</strong> {{HOURS}}</p></div>
        <div><h3>Visit</h3><p class="small">{{ADDRESS}}<br>{{CITY}}, {{STATE}} {{ZIP}}</p></div>
      </div>
      <div class="subfooter"><div class="small">© <span id="year"></span> {{BUSINESS_NAME}}</div><div class="small muted">{{CITY}}, {{STATE}}</div></div>
    </div>
  </footer>
</body>
</html>"}
{"path":"contact.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Contact | {{BUSINESS_NAME}}</title>
  <meta name="description" content="Contact {{BUSINESS_NAME}} — call {{PHONE}} or email {{EMAIL}}. Visit us at {{ADDRESS}}, {{CITY}}, {{STATE}} {{ZIP}}.">
  <link rel="canonical" href="/contact.html">
  <meta property="og:title" content="Contact {{BUSINESS_NAME}}">
  <meta property="og:description" content="We’re here to help. Call, email, or send a message.">
  <meta property="og:type" content="website">
  <meta property="og:url" content="/contact.html">
  <meta property="og:image" content="assets/img/hero-abstract.svg">
  <meta property="og:image:alt" content="Contact us">
  <meta property="og:site_name" content="{{BUSINESS_NAME}}">
  <meta name="twitter:card" content="summary_large_image">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
  <script type="application/ld+json">
  {
    "@context":"https://schema.org",
    "@type":"HVACBusiness",
