    "telephone":"{{PHONE}}",
    "email":"{{EMAIL}}",
    "address":{"@type":"PostalAddress","streetAddress":"{{ADDRESS}}","addressLocality":"{{CITY}}","addressRegion":"{{STATE}}","postalCode":"{{ZIP}}"},
    "openingHours":"{{HOURS}}"
  }
  </script>
</head>
<body>
  <a href="#main" class="skip-link">Skip to content</a>
  <header class="header" role="banner">
    <div class="topbar"><div><a href="tel:{{PHONE}}"><strong>{{PHONE}}</strong></a> <span class="muted">•</span> <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div><div class="small">Open today: {{HOURS}}</div></div>
    <nav class="nav" aria-label="Primary">
      <a class="logo" href="/"><span class="logo-mark" aria-hidden="true"></span><span class="logo-title">{{BUSINESS_NAME}}</span></a>
      <button id="menuToggle" class="nav-toggle" aria-expanded="false" aria-controls="siteMenu" aria-label="Toggle menu"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M3 6h18v2H3zm0 5h18v2H3zm0 5h18v2H3z"/></svg></button>
      <div class="menu" id="siteMenu">
        <a href="/services.html">Services</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/financing.html">Financing</a>
        <a href="/about.html">About</a>
        <a href="/reviews.html">Reviews</a>
        <a href="/book.html" class="badge">Book</a>
        <a href="/contact.html" aria-current="page">Contact</a>
      </div>
      <div class="menu-actions">
        <a class="btn btn-secondary" href="tel:{{PHONE}}">Call {{PHONE}}</a>
        <a class="btn btn-primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </nav>
  </header>

  <main id="main">
    <section class="section hero" aria-label="Contact hero">
      <div class="container">
        <div>
          <span class="badge">We’re here to help</span>
          <h1>Contact {{BUSINESS_NAME}}</h1>
          <p class="lead">Call, email, or send a message. Our team in {{CITY}}, {{STATE}} will get right back to you.</p>
        </div>
        <div aria-hidden="true" class="hero-visual"><img src="assets/img/hero-abstract.svg" alt="" style="border-radius:16px; border:1px solid var(--muted-200)"></div>
      </div>
    </section>

    <section class="section">
      <div class="container grid grid-2">
        <form class="card js-validate" method="post" action="#" novalidate>
          <h2 class="mt-0">Send a message</h2>
          <div class="form-grid">
            <div class="field"><label for="cname">Full name</label><input class="input" id="cname" name="name" required autocomplete="name"></div>
            <div class="field"><label for="cemail">Email</label><input class="input" id="cemail" name="email" type="email" required autocomplete="email"></div>
            <div class="field"><label for="cphone">Phone</label><input class="input" id="cphone" name="phone" type="tel" required autocomplete="tel"></div>
            <div class="field"><label for="csubject">Subject</label><input class="input" id="csubject" name="subject" required></div>
          </div>
          <div class="field"><label for="cmsg">Message</label><textarea class="textarea" id="cmsg" name="message" rows="6" required></textarea></div>
          <button class="btn btn-primary" type="submit">Send message</button>
          <p class="small muted mt-1">Prefer to talk? Call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
        </form>
        <aside class="card">
          <h2 class="mt-0">Visit or call</h2>
          <p class="small"><strong>Address</strong><br>{{ADDRESS}}<br>{{CITY}}, {{STATE}} {{ZIP}}</p>
          <p class="small"><strong>Phone</strong><br><a href="tel:{{PHONE}}">{{PHONE}}</a></p>
          <p class="small"><strong>Email</strong><br><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p class="small"><strong>Hours</strong><br>{{HOURS}}</p>
          <hr>
          <p class="small muted">Parking available on site. Wheelchair accessible entrance.</p>
        </aside>
      </div>
    </section>
  </main>

  <footer class="footer" role="contentinfo">
    <div class="container section">
      <div class="cols">
        <div><a class="logo" href="/"><span class="logo-mark" aria-hidden="true"></span><span class="logo-title">{{BUSINESS_NAME}}</span></a><p class="mt-2">{{TAGLINE}}</p></div>
        <div><h3>Call or write</h3><p class="small"><a href="tel:{{PHONE}}">{{PHONE}}</a><br><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p></div>
